#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i = 0; i < 10; i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    vector<vector<bool>> has_edge;

    for(int i = 0; i < m; i++){
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    bool small = (n <= 5000);
    if(small){
        has_edge.assign(n+1, vector<bool>(n+1, false));
        for(int u = 1; u <= n; u++) for(int v : adj[u]) has_edge[u][v] = true;
    }

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){ return chrono::duration_cast<chrono::milliseconds>(now() - start_time).count(); };

    mt19937 rng(42);
    vector<int> best_path;

    while(elapsed_ms() < 3800 && (int)best_path.size() < n){
        int sv = rng() % n + 1;
        vector<int> path;
        vector<bool> used(n+1, false);
        path.push_back(sv);
        used[sv] = true;

        // Greedy extend from back
        auto extend_back = [&]() -> bool {
            int tail = path.back();
            vector<int> cands;
            for(int v : adj[tail]) if(!used[v]) cands.push_back(v);
            if(cands.empty()) return false;
            // Pick random among top candidates (fewest outgoing unused)
            int pick = cands[rng() % cands.size()];
            path.push_back(pick);
            used[pick] = true;
            return true;
        };

        auto extend_front = [&]() -> bool {
            int head = path[0];
            vector<int> cands;
            for(int v : radj[head]) if(!used[v]) cands.push_back(v);
            if(cands.empty()) return false;
            int pick = cands[rng() % cands.size()];
            path.insert(path.begin(), pick);
            used[pick] = true;
            return true;
        };

        while(extend_back());
        while(extend_front());
        while(extend_back());
        while(extend_front());

        // Try vertex insertion if graph is small
        if(small){
            bool improved = true;
            while(improved && elapsed_ms() < 3800){
                improved = false;
                for(int w = 1; w <= n && !improved; w++){
                    if(used[w]) continue;
                    for(int i = 0; i+1 < (int)path.size() && !improved; i++){
                        if(has_edge[path[i]][w] && has_edge[w][path[i+1]]){
                            path.insert(path.begin()+i+1, w);
                            used[w] = true;
                            improved = true;
                        }
                    }
                }
            }
        }

        if((int)path.size() > (int)best_path.size()) best_path = path;
    }

    cout << best_path.size() << "\n";
    for(int i = 0; i < (int)best_path.size(); i++){
        if(i) cout << ' ';
        cout << best_path[i];
    }
    cout << "\n";
}
